// Package postgres implements artifact.Repository against PostgreSQL
// via jackc/pgx. The queries are generated by sqlc from queries.sql.
package postgres

import (
	"context"
	"errors"
	"time"

	"github.com/jackc/pgx/v5"
	"github.com/jackc/pgx/v5/pgtype"
	"github.com/jackc/pgx/v5/pgxpool"

	"github.com/garamsh/garam/cowork/internal/artifact"
	"github.com/garamsh/garam/cowork/internal/artifact/postgres/db"
	"github.com/garamsh/garam/lib/errorx"
	"github.com/garamsh/garam/lib/grn"
)

// Repository implements artifact.Repository against PostgreSQL.
type Repository struct {
	pool *pgxpool.Pool
}

var _ artifact.Repository = (*Repository)(nil)

// New answers a repository over pool.
func New(pool *pgxpool.Pool) *Repository {
	return &Repository{pool: pool}
}

func translate(err error, op string, notFound error) error {
	switch {
	case err == nil:
		return nil
	case errors.Is(err, pgx.ErrNoRows):
		return notFound
	case errorx.KindOf(err) != errorx.KindUnknown:
		return err
	}
	return errorx.Wrap(err, "artifacts: "+op, errorx.KindUnavailable)
}

func timestamp(t time.Time) pgtype.Timestamptz { return pgtype.Timestamptz{Time: t, Valid: true} }

func artifactOf(r db.Artifact) (artifact.Artifact, error) {
	creator, err := grn.Parse(r.CreatedBy)
	if err != nil {
		return artifact.Artifact{}, errorx.Wrap(err, "artifacts: stored creator", errorx.KindDataLoss)
	}
	return artifact.Artifact{
		ID: r.ID, Org: r.Org, Kind: artifact.Kind(r.Kind), Title: r.Title, Latest: int(r.Latest),
		CreatedBy: creator, CreatedAt: r.CreatedAt.Time, UpdatedAt: r.UpdatedAt.Time,
	}, nil
}

func versionOf(r db.ArtifactVersion) (artifact.Version, error) {
	creator, err := grn.Parse(r.CreatedBy)
	if err != nil {
		return artifact.Version{}, errorx.Wrap(err, "artifacts: stored creator", errorx.KindDataLoss)
	}
	return artifact.Version{
		Artifact: r.ArtifactID, Number: int(r.Number), BlobKey: r.BlobKey, ContentType: r.ContentType,
		Size: r.Size, SHA256: r.Sha256, CreatedBy: creator, CreatedAt: r.CreatedAt.Time,
	}, nil
}

func insertVersion(ctx context.Context, q *db.Queries, org string, v artifact.Version) error {
	return q.InsertVersion(ctx, db.InsertVersionParams{
		Org: org, ArtifactID: v.Artifact, Number: int32(v.Number), BlobKey: v.BlobKey, ContentType: v.ContentType,
		Size: v.Size, Sha256: v.SHA256, CreatedBy: v.CreatedBy.String(), CreatedAt: timestamp(v.CreatedAt),
	})
}

// Create implements artifact.Repository.
func (r *Repository) Create(ctx context.Context, a artifact.Artifact, v artifact.Version) error {
	err := pgx.BeginFunc(ctx, r.pool, func(tx pgx.Tx) error {
		q := db.New(tx)
		if err := q.InsertArtifact(ctx, db.InsertArtifactParams{
			Org: a.Org, ID: a.ID, Kind: string(a.Kind), Title: a.Title, Latest: int32(a.Latest),
			CreatedBy: a.CreatedBy.String(), CreatedAt: timestamp(a.CreatedAt), UpdatedAt: timestamp(a.UpdatedAt),
		}); err != nil {
			return err
		}
		return insertVersion(ctx, q, a.Org, v)
	})
	return translate(err, "create", artifact.ErrArtifactNotFound)
}

// AddVersion implements artifact.Repository.
func (r *Repository) AddVersion(ctx context.Context, org string, v artifact.Version) (artifact.Artifact, artifact.Version, error) {
	var a artifact.Artifact
	err := pgx.BeginFunc(ctx, r.pool, func(tx pgx.Tx) error {
		q := db.New(tx)
		row, err := q.NextVersion(ctx, db.NextVersionParams{Org: org, ID: v.Artifact, UpdatedAt: timestamp(v.CreatedAt)})
		if err != nil {
			return err
		}
		if a, err = artifactOf(row); err != nil {
			return err
		}
		v.Number = a.Latest
		return insertVersion(ctx, q, org, v)
	})
	if err != nil {
		return artifact.Artifact{}, artifact.Version{}, translate(err, "save", artifact.ErrArtifactNotFound)
	}
	return a, v, nil
}

// Get implements artifact.Repository.
func (r *Repository) Get(ctx context.Context, org, id string) (artifact.Artifact, error) {
	row, err := db.New(r.pool).GetArtifact(ctx, db.GetArtifactParams{Org: org, ID: id})
	if err != nil {
		return artifact.Artifact{}, translate(err, "get", artifact.ErrArtifactNotFound)
	}
	return artifactOf(row)
}

// List implements artifact.Repository.
func (r *Repository) List(ctx context.Context, org string, limit int) ([]artifact.Artifact, error) {
	rows, err := db.New(r.pool).ListArtifacts(ctx, db.ListArtifactsParams{Org: org, Lim: int32(limit)})
	if err != nil {
		return nil, translate(err, "list", artifact.ErrArtifactNotFound)
	}
	out := make([]artifact.Artifact, len(rows))
	for i, row := range rows {
		if out[i], err = artifactOf(row); err != nil {
			return nil, err
		}
	}
	return out, nil
}

// Versions implements artifact.Repository.
func (r *Repository) Versions(ctx context.Context, org, id string) ([]artifact.Version, error) {
	rows, err := db.New(r.pool).ListVersions(ctx, db.ListVersionsParams{Org: org, ArtifactID: id})
	if err != nil {
		return nil, translate(err, "versions", artifact.ErrArtifactNotFound)
	}
	out := make([]artifact.Version, len(rows))
	for i, row := range rows {
		if out[i], err = versionOf(row); err != nil {
			return nil, err
		}
	}
	return out, nil
}

// Version implements artifact.Repository.
func (r *Repository) Version(ctx context.Context, org, id string, number int) (artifact.Version, error) {
	row, err := db.New(r.pool).GetVersion(ctx, db.GetVersionParams{Org: org, ArtifactID: id, Number: int32(number)})
	if err != nil {
		return artifact.Version{}, translate(err, "version", artifact.ErrVersionNotFound)
	}
	return versionOf(row)
}
